package model

import "time"

// User represents a registered user in the database.
type User struct {
	// ID is the unique identifier generated by PostgreSQL.
	ID string `json:"id"`

	// PhoneNumber uniquely identifies the user's account.
	PhoneNumber string `json:"phone_number"`

	// CreatedAt records when the account was created.
	CreatedAt time.Time `json:"created_at"`

	// UpdatedAt records the last modification time.
	UpdatedAt time.Time `json:"updated_at"`
}
